import React from 'react';
import { Grommet, Box, Data, DataSearch, DataFilters, Text } from 'grommet';
import { Search, Filter } from 'grommet-icons';

const allItems = [
  { name: 'Apex-Server', status: 'Ready' },
  { name: 'ECAAS3', status: 'Ready' },
  { name: 'AuroraEdge', status: 'Paused' },
  { name: 'EdgeSite1', status: 'Paused' },
  { name: 'california_1', status: 'Paused' },
  { name: 'Host-42', status: 'Ready' },
  { name: 'Host-99', status: 'Ready' },
];

export const BugRepro = () => {
  const [data, setData] = React.useState(allItems);

  // Filter logic for search
  const onSearch = (search) => {
    const term = search.search.trim().toLowerCase();
    setData(allItems.filter(item => item.name.toLowerCase().includes(term)));
  };

  // Filter logic for status drop‐down
  const onFilter = (filters) => {
    const statusFilter = filters.find(f => f.property === 'status');
    if (statusFilter && statusFilter.value && statusFilter.value.length) {
      setData(allItems.filter(item => statusFilter.value.includes(item.status)));
    } else {
      setData(allItems);
    }
  };

  return (
    <Grommet>
      <Box pad="medium" background="dark-1" fill>
        <Text size="large" weight="bold" margin={{ bottom: 'small' }}>
          Servers
        </Text>
        <Data
          data={data}
          columns={[
            { property: 'name', header: <Text>Name</Text> },
            { property: 'status', header: <Text>Status</Text> },
          ]}
          // Toolbar only contains DataSearch and DataFilters
          toolbar={
            <Box direction="row" gap="small">
              <DataSearch
                icon={<Search />}
                placeholder="Search"
                onSearch={onSearch}
                closable
              />
              <DataFilters
                data={allItems}
                dropIcon={<Filter />}
                properties={[{ property: 'status', label: 'Status' }]}
                onFilter={onFilter}
              />
              {/* Expecting a Clear Filters button here, but it never appears */}
            </Box>
          }
        />
      </Box>
    </Grommet>
  );
};
